def load() -> pd.DataFrame:
    import glob
    files = glob.glob("data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*")
    dfs = []
    for f in files:
        df = pd.read_csv(f, encoding='latin-1')
        df['source_file'] = f
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

def process(join_and_filter) -> pd.DataFrame:
    avg = join_and_filter['reports'].mean()
    return pd.DataFrame({'average_reports': [round(avg, 4)]})
